def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return min(budget, 1.0)

    prev_bids = []
    opp_pressures = []
    desperate_count = 0
    rich_count = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        opp_hp = opp.get('hp', 10)
        opp_nw = opp.get('no_water_days', 0)
        opp_budget = opp.get('budget', 0)
        opp_salary = opp.get('daily_salary', DAILY_SALARY)
        opp_req = opp.get('water_requirement', WATER_REQ)

        pressure = 0.0
        if opp_hp <= 3:
            pressure += 2.0
        elif opp_hp <= 5:
            pressure += 1.0
        if opp_nw >= 1:
            pressure += 1.5
        if opp_budget >= opp_salary * 4:
            pressure += 0.8
        if opp_req > WATER_REQ:
            pressure += 0.3
        opp_pressures.append(pressure)

        if opp_hp <= 4 or opp_nw >= 1:
            desperate_count += 1
        if opp_budget >= 280:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    pressure_max = max(opp_pressures) if opp_pressures else 0.0

    winners_est = max(1, min(2, int(supply // WATER_REQ)))
    scarcity = 2 - winners_est

    urgency = 0.0
    if hp <= 2:
        urgency += 3.0
    elif hp <= 4:
        urgency += 2.0
    elif hp <= 6:
        urgency += 1.0
    if no_water >= 2:
        urgency += 3.0
    elif no_water >= 1:
        urgency += 1.5
    urgency += scarcity * 0.8

    if budget <= DAILY_SALARY:
        urgency += 0.8
    elif budget >= DAILY_SALARY * 5:
        urgency -= 0.3

    if day >= 8:
        urgency += 0.7

    if urgency >= 5.0:
        target = max(highest_prev + 3.0, avg_prev + 8.0, DAILY_SALARY * 1.45)
    elif urgency >= 3.5:
        target = max(highest_prev + 1.5, avg_prev + 3.0, DAILY_SALARY * 1.12)
    elif urgency >= 2.0:
        target = max(avg_prev * 0.96, DAILY_SALARY * 0.92)
    else:
        target = DAILY_SALARY * 0.28

    if pressure_max >= 2.5 and urgency < 3.5:
        target *= 0.82
    if desperate_count >= 2 and urgency < 5.0:
        target *= 0.88
    if rich_count == 0 and urgency >= 2.0:
        target *= 0.96

    if winners_est >= 2 and urgency < 3.5:
        target *= 0.9
    elif winners_est == 1 and urgency >= 2.0:
        target *= 1.08

    min_keep = 0.0
    if day <= 7:
        min_keep = DAILY_SALARY * 1.2
    elif day <= 9:
        min_keep = DAILY_SALARY * 0.6

    spend_cap = budget
    if urgency < 5.0:
        spend_cap = max(0.0, budget - min_keep)
        if spend_cap <= 0:
            spend_cap = min(budget, DAILY_SALARY * 0.35)

    bid = min(target, spend_cap if spend_cap > 0 else budget)

    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, highest_prev + 4.0, DAILY_SALARY * 1.3))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer aggressiveness.
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many "water units" we can cover today.
    # If supply is low relative to WATER_REQ, we need to be more competitive.
    supply_units = supply / WATER_REQ  # float

    # Base bid: aim for moderate share of salary.
    # If supply is scarce (<= 2 units), increase slightly.
    scarcity_factor = 1.0
    if supply_units <= 1.8:
        scarcity_factor = 1.15
    elif supply_units <= 2.2:
        scarcity_factor = 1.05

    # Aggression response: avoid repeating Alex/Cindy extreme bidding.
    # If someone was bidding extremely high yesterday, we don't mirror; we undercut.
    # Thresholds tuned to observed meta-round behavior.
    extreme_th = DAILY_SALARY * 1.25  # 112.5
    high_th = DAILY_SALARY * 0.95     # 85.5

    if highest_prev_bid >= extreme_th:
        # They likely overcommitted; bid below their likely level.
        base = DAILY_SALARY * 0.62
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.85
    elif highest_prev_bid >= high_th:
        base = DAILY_SALARY * 0.68
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.9
    else:
        base = DAILY_SALARY * 0.55
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.8

    # If my hp is already healthy, don't overpay.
    if hp >= 7 and no_water_days <= 1:
        base *= 0.92

    # If hp is low, we must secure water.
    if hp <= 3 or no_water_days >= 3:
        base *= 1.18

    bid = base * scarcity_factor

    # Safety caps based on budget.
    # Also avoid bidding above a reasonable fraction of budget.
    max_bid_frac = 0.95
    if budget <= 0:
        return 0.0

    bid = min(bid, budget * max_bid_frac)

    # Ensure bid is non-negative.
    if bid < 0:
        bid = 0.0

    # If budget is tiny, still bid what we can.
    if budget < DAILY_SALARY * 0.2:
        bid = min(budget, DAILY_SALARY * 0.25)

    return float(bid)

